export function resolveConflictsUsingTreeOfThoughts(modules, confidenceScores) {
  const branches = modules.map((module, index) => ({
    module: module,
    confidence: confidenceScores[index]
  }));

  branches.sort((a, b) => b.confidence - a.confidence);

  const selectedBranch = branches[0];

  return selectedBranch.module;
}
